
-- ==================== 00_reset.sql ====================
-- ATTENTION : supprime toutes les données métier locales.
BEGIN;
TRUNCATE TABLE note_critere, rapport_scouting, joueur, club RESTART IDENTITY CASCADE;
COMMIT;

-- ==================== 01_clubs.sql ====================
-- Clubs réels européens — instantané vérifié le 20 juillet 2026.
BEGIN;
SELECT setval(pg_get_serial_sequence('club','id'), (SELECT MAX(id) FROM club));
COMMIT;

-- ==================== 02_joueurs.sql ====================
-- Joueurs réels et clubs réels — positions/nationalités publiques.
-- Les champs optionnels date_naissance, pied_fort, taille et poids restent NULL pour éviter des valeurs non vérifiées.
BEGIN;
SELECT setval(pg_get_serial_sequence('joueur','id'), (SELECT MAX(id) FROM joueur));
COMMIT;

-- ==================== 03_rapports.sql ====================
-- Rapports de scouting SYNTHÉTIQUES associés à de vrais joueurs.
-- Ne pas présenter ces commentaires comme des évaluations professionnelles réelles.
BEGIN;
SELECT setval(pg_get_serial_sequence('rapport_scouting','id'), (SELECT MAX(id) FROM rapport_scouting));
COMMIT;

-- ==================== 04_notes.sql ====================
-- Notes SYNTHÉTIQUES de 0 à 100. Elles servent uniquement aux tests CRUD, filtres et futur RAG.
BEGIN;
SELECT setval(pg_get_serial_sequence('note_critere','id'), (SELECT MAX(id) FROM note_critere));
COMMIT;

-- ==================== 05_scores.sql ====================
-- Le chargement SQL direct contourne le service Spring : on recalcule donc score_global ici.
BEGIN;
UPDATE rapport_scouting r
SET score_global = s.moyenne
FROM (
    SELECT rapport_id, ROUND(AVG(note_sur_100))::INTEGER AS moyenne
    FROM note_critere
    GROUP BY rapport_id
) s
WHERE r.id = s.rapport_id;

UPDATE rapport_scouting
SET recommandation = CASE
    WHEN score_global >= 87 THEN 'RECOMMANDE'
    WHEN score_global >= 80 THEN 'A_SUIVRE'
    ELSE 'A_DEVELOPPER'
END;
COMMIT;

-- ==================== 06_verify.sql ====================
SELECT 'clubs' AS table_name, COUNT(*) AS total FROM club
UNION ALL SELECT 'joueurs', COUNT(*) FROM joueur
UNION ALL SELECT 'rapports', COUNT(*) FROM rapport_scouting
UNION ALL SELECT 'notes', COUNT(*) FROM note_critere;

SELECT c.nom AS club, COUNT(j.id) AS joueurs
FROM club c LEFT JOIN joueur j ON j.club_id = c.id
GROUP BY c.id, c.nom ORDER BY c.id;

SELECT j.prenom, j.nom, c.nom AS club, j.poste_principal, j.nationalite, r.score_global, r.recommandation
FROM joueur j
JOIN club c ON c.id = j.club_id
JOIN rapport_scouting r ON r.joueur_id = j.id
ORDER BY r.score_global DESC, j.nom
LIMIT 20;
